<script>document.addEventListener('DOMContentLoaded',()=>{const i=document.getElementById('thumbnail'),p=document.querySelector('.studio-artwork-preview'),title=document.querySelector('input[name=title]'),slug=document.getElementById('cartoon-slug');let slugEdited=Boolean(slug?.value);slug?.addEventListener('input',()=>slugEdited=true);title?.addEventListener('input',()=>{if(slugEdited)return;slug.value=title.value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,190)});i?.addEventListener('change',()=>{const f=i.files?.[0];if(f){const u=URL.createObjectURL(f);p.innerHTML='<img src="'+u+'" alt="Artwork preview">'}});});</script>
